package dev.trentdb.storage;import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;import java.nio.file.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;class DuckDbPrimitiveSegmentScanTest{@TempDir Path d;@Test void iterates2048PlusOneAcrossBlocks(){var p=d.resolve("scan");try(var w=SingleFileBlockManager.create(p,new byte[16])){byte[] a=new byte[w.usableBlockSize()],b=new byte[w.usableBlockSize()];for(int i=0;i<2048;i++){a[i*4]=(byte)i;a[i*4+1]=(byte)(i>>>8);}a[4*2047+1]=(byte)(2047>>>8);b[0]=0;b[1]=8;w.writeBlock(0,a);w.writeBlock(1,b);}try(var m=SingleFileBlockManager.openMetadataReadOnly(p)){var scan=new DuckDbPrimitiveSegmentScan(m,DuckDbTableCreateInfo.ScalarLogicalType.INTEGER,List.of(s(2048,0,0,0,2047),s(1,1,0,2048,2048)),List.of(),2049);var first=scan.next();var second=scan.next();assertEquals(0,first.rowStart());assertEquals(2048,first.values().size());assertEquals(2047L,first.values().get(2047));assertEquals(2048,second.rowStart());assertEquals(List.of(2048L),second.values());assertFalse(scan.hasNext());}}private static DuckDbPrimitiveColumnMetadata.Segment s(long n,long b,long o,long min,long max){return new DuckDbPrimitiveColumnMetadata.Segment(n,new DuckDbPrimitiveColumnMetadata.BlockPointer(b,o),1,new DuckDbPrimitiveColumnMetadata.Statistics(false,true,n,OptionalLong.of(min),OptionalLong.of(max)));}}
